import { queryOptions } from "@tanstack/react-query";

import { getApiFetch } from "../routes/api.$";

export const healthQueryOptions = queryOptions({
  queryFn: async () => {
    const response = await getApiFetch()("/api/health", {
      body: {},
      headers: {},
      method: "GET",
    });

    if (response.error || !response.data) {
      throw new Error("Health check failed");
    }

    return response.data;
  },
  queryKey: ["api", "health"] as const,
  retry: false,
  staleTime: 30_000,
});

import type { AdminAccess } from "../server/modules/models";

export const adminRoutePermissions = {
  applications: "applications:read",
  serviceAccounts: "service-accounts:read",
  systemRoles: "system-roles:read",
  teams: "teams:read",
  users: "users:read",
} as const;

export type AdminRoutePermission =
  (typeof adminRoutePermissions)[keyof typeof adminRoutePermissions];

export function hasAdminPermission(access: AdminAccess | undefined, permission: string) {
  return Boolean(access?.permissions.includes("*") || access?.permissions.includes(permission));
}

export function firstAdminPath(access: AdminAccess) {
  if (hasAdminPermission(access, adminRoutePermissions.users)) return "/admin/users" as const;
  if (hasAdminPermission(access, adminRoutePermissions.teams)) return "/admin/teams" as const;
  if (hasAdminPermission(access, adminRoutePermissions.applications)) {
    return "/admin/applications" as const;
  }
  if (hasAdminPermission(access, adminRoutePermissions.serviceAccounts)) {
    return "/admin/service-accounts" as const;
  }
  if (hasAdminPermission(access, adminRoutePermissions.systemRoles)) {
    return "/admin/system-roles" as const;
  }
  return "/admin/users" as const;
}

import { queryOptions } from "@tanstack/react-query";

import { authClient } from "./auth-client";

export const authQueryKeys = {
  session: ["auth", "session"] as const,
};

export const sessionQueryOptions = queryOptions({
  queryFn: async () => {
    const { data, error } = await authClient.getSession();

    if (error?.status === 401) {
      return null;
    }

    if (error) {
      throw error;
    }

    return data ?? null;
  },
  queryKey: authQueryKeys.session,
  retry: false,
  staleTime: 60_000,
});

export class AuthApiError extends Error {
  constructor(
    message: string,
    readonly status: number,
  ) {
    super(message);
    this.name = "AuthApiError";
  }
}

export async function authFetch<T>(path: string, init: RequestInit = {}) {
  const headers = new Headers(init.headers);
  if (init.body && !headers.has("content-type")) headers.set("content-type", "application/json");

  const response = await fetch(`/api${path}`, { ...init, headers });
  const body = (await response.json().catch(() => null)) as { error?: string } | T | null;
  if (!response.ok) {
    throw new AuthApiError(readErrorMessage(body), response.status);
  }

  return body as T;
}

export function safeRedirect(value: string | undefined, fallback = "/") {
  if (!value || !value.startsWith("/") || value.startsWith("//")) return fallback;
  return value;
}

export function formatAuthError(error: unknown) {
  if (error instanceof AuthApiError && error.status === 429) {
    return "Too many attempts. Wait a moment and try again.";
  }

  if (error instanceof Error && error.message) return error.message;
  return "The request could not be completed.";
}

function readErrorMessage(value: unknown) {
  if (value && typeof value === "object" && "error" in value && typeof value.error === "string") {
    return value.error;
  }

  return "The request could not be completed.";
}

import { redirect } from "@tanstack/react-router";
import type { QueryClient } from "@tanstack/react-query";

import { ApiClientError, type AdminAccess } from "./api-client";
import { adminAccessQueryOptions } from "./api-query-options";
import { safeRedirect } from "./auth-api";
import { hasAdminPermission, type AdminRoutePermission } from "./admin-policy";

export { adminRoutePermissions, firstAdminPath, hasAdminPermission } from "./admin-policy";
export type { AdminRoutePermission } from "./admin-policy";

export async function requireAdminAccess(queryClient: QueryClient, from: string) {
  try {
    return await queryClient.fetchQuery({ ...adminAccessQueryOptions, staleTime: 0 });
  } catch (error) {
    if (error instanceof ApiClientError && error.status === 401) {
      throw redirect({
        to: "/sign-in",
        search: { redirect: safeRedirect(from, "/admin") },
      });
    }

    if (error instanceof ApiClientError && error.status === 403) {
      throw redirect({
        to: "/forbidden",
        search: { from: safeRedirect(from, "/admin") },
      });
    }

    throw error;
  }
}

export function requireAdminPermission(
  access: AdminAccess,
  permission: AdminRoutePermission,
  from: string,
) {
  if (hasAdminPermission(access, permission)) return;

  throw redirect({
    to: "/forbidden",
    search: { from: safeRedirect(from, "/admin") },
  });
}

import type {
  BootstrapCompleteBody,
  BootstrapTokenBody,
  ApplicationAssignmentBody,
  ApplicationClientCreateBody,
  ApplicationClientUpdateBody,
  ApplicationCreateBody,
  ApplicationRoleCreateBody,
  ApplicationRoleGrantBody,
  ApplicationRoleUpdateBody,
  ApplicationUpdateBody,
  InvitationAcceptBody,
  InvitationCreateBody,
  OwnershipBody,
  ServiceAccountCreateBody,
  ServiceAccountCredentialCreateBody,
  ServiceAccountCredentialRotateBody,
  ServiceAccountUpdateBody,
  TeamCreateBody,
